using Arcoll.WinUI3.Services;
using Microsoft.UI.Xaml;
using Microsoft.UI.Xaml.Automation;
using Microsoft.UI.Xaml.Controls;
using Microsoft.UI.Xaml.Media;
using Microsoft.UI.Xaml.Media.Animation;
using Microsoft.UI.Xaml.Shapes;
namespace Arcoll.WinUI3.Controls;
/// <summary>Shared themed data gate. It emits a request; it never starts installation, cleanup or other writes.</summary>
public sealed class PageLoadingView:Grid
{
 private readonly Button _circle=new(){Width=236,Height=236,Padding=new Thickness(0),BorderThickness=new Thickness(0),CornerRadius=new CornerRadius(118),Background=new SolidColorBrush(Microsoft.UI.Colors.Transparent)};
 private readonly ProgressRing _ring=new(){Width=230,Height=230,Minimum=0,Maximum=100,IsHitTestVisible=false};
 private readonly Ellipse _halo=new(){Width=266,Height=266,StrokeThickness=1,Opacity=.4,IsHitTestVisible=false};
 private readonly TextBlock _tag=new(){Text="COLETA DE DADOS",FontSize=9,CharacterSpacing=160,HorizontalAlignment=HorizontalAlignment.Center};
 private readonly TextBlock _value=new(){Text="COLETAR",FontSize=22,FontWeight=Microsoft.UI.Text.FontWeights.SemiBold,HorizontalAlignment=HorizontalAlignment.Center};
 private readonly TextBlock _title=new(){FontSize=16,FontWeight=Microsoft.UI.Text.FontWeights.SemiBold,TextAlignment=TextAlignment.Center,TextWrapping=TextWrapping.Wrap,MaxWidth=430};
 private readonly TextBlock _stage=new(){FontSize=12,TextAlignment=TextAlignment.Center,TextWrapping=TextWrapping.Wrap,MaxWidth=430};
 private readonly TextBlock _hint=new(){FontSize=10,TextAlignment=TextAlignment.Center,TextWrapping=TextWrapping.Wrap,MaxWidth=400};
 private readonly Button _options=new(){Content="Escolher opções antes de coletar",Padding=new Thickness(12,6,12,6),FontSize=11};
 private readonly Button _cancel=new(){Content="Interromper coleta",Padding=new Thickness(12,6,12,6),FontSize=11};private long _cancelOperation=-1,_shownOperation;
 private readonly Storyboard _pulse=new();private bool _busy,_allowed,_animating;
 public event Action? CancelRequested;public event Action? CollectRequested;public event Action? OptionsRequested;
 public PageLoadingView(){var layout=new StackPanel{Spacing=12,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,Padding=new Thickness(20)};var zone=new Grid{Width=280,Height=280};zone.Children.Add(_halo);var circle=new Grid();circle.Children.Add(_ring);var copy=new StackPanel{Spacing=9,VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,IsHitTestVisible=false};copy.Children.Add(_tag);copy.Children.Add(_value);circle.Children.Add(copy);_circle.Content=circle;zone.Children.Add(_circle);layout.Children.Add(zone);layout.Children.Add(_title);layout.Children.Add(_stage);layout.Children.Add(_hint);_options.HorizontalAlignment=HorizontalAlignment.Center;_cancel.HorizontalAlignment=HorizontalAlignment.Center;layout.Children.Add(_options);layout.Children.Add(_cancel);Children.Add(new ScrollViewer{Content=layout,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden,HorizontalAlignment=HorizontalAlignment.Stretch,VerticalAlignment=VerticalAlignment.Stretch,VerticalContentAlignment=VerticalAlignment.Center});_circle.Click+=(_,_)=>{if(!_busy&&_allowed)CollectRequested?.Invoke();};_options.Click+=(_,_)=>OptionsRequested?.Invoke();_cancel.Click+=(_,_)=>{_cancelOperation=_shownOperation;_cancel.IsEnabled=false;_hint.Text="Solicitando a interrupção da coleta…";CancelRequested?.Invoke();};AutomationProperties.SetName(_circle,"Coletar dados da página");AutomationProperties.SetAutomationId(_circle,"page-data-collect");AutomationProperties.SetLiveSetting(_stage,Microsoft.UI.Xaml.Automation.Peers.AutomationLiveSetting.Polite);
 var pulse=new DoubleAnimation{From=.18,To=.65,Duration=new Duration(TimeSpan.FromSeconds(1.5)),AutoReverse=true,RepeatBehavior=RepeatBehavior.Forever};Storyboard.SetTarget(pulse,_halo);Storyboard.SetTargetProperty(pulse,"Opacity");_pulse.Children.Add(pulse);Unloaded+=(_,_)=>{Suspend();};Loaded+=(_,_)=>Animate();}
 public void Paint(LoadingColors c){Background=ThemeService.Brush(c.Surface);_title.Foreground=_value.Foreground=ThemeService.Brush(c.Text);_stage.Foreground=_hint.Foreground=ThemeService.Brush(c.Muted);_tag.Foreground=_ring.Foreground=ThemeService.Brush(c.Accent);_ring.Background=ThemeService.Brush(c.Track);_halo.Stroke=ThemeService.Brush(c.Accent);_options.Foreground=ThemeService.Brush(c.Text);_options.Background=ThemeService.Brush(c.Surface);_options.BorderBrush=ThemeService.Brush(c.Track);_cancel.Foreground=ThemeService.Brush(c.Text);_cancel.Background=ThemeService.Brush(c.Surface);_cancel.BorderBrush=ThemeService.Brush(c.Track);_circle.Foreground=ThemeService.Brush(c.Text);_circle.Resources["ButtonBackgroundPointerOver"]=ThemeService.Brush(c.Surface);_circle.Resources["ButtonBackgroundPressed"]=ThemeService.Brush(c.Surface);_circle.Resources["ButtonBackgroundDisabled"]=ThemeService.Brush(c.Surface);}
 public void Present(string title,DataLoadSnapshot state,bool allowed,bool options,bool canCancel=false){_shownOperation=state.Operation;_busy=state.Phase==DataLoadPhase.Loading;_cancel.Visibility=_busy&&canCancel?Visibility.Visible:Visibility.Collapsed;_cancel.IsEnabled=allowed&&_busy&&_cancelOperation!=state.Operation;_title.Text=title;_stage.Text=state.Stage;_value.Text=_busy?(state.Percent.HasValue?state.Percent+"%":"…"):state.Phase==DataLoadPhase.Failed?"TENTAR":"COLETAR";_value.FontSize=_busy?48:22;_allowed=allowed;_circle.IsEnabled=allowed;_circle.IsHitTestVisible=allowed&&!_busy;_circle.IsTabStop=allowed&&!_busy;_ring.IsIndeterminate=_busy&&!state.Percent.HasValue;_ring.Value=_busy?state.Percent??0:18;_ring.IsActive=true;_hint.Text=!allowed?"Conecte e autorize o gestor para consultar os dados.":_busy?"Aguarde a conclusão da consulta. Você pode navegar para outra área.":state.Phase==DataLoadPhase.Failed?"Clique no círculo para tentar novamente.":"Clique no círculo para iniciar a coleta desta área.";_options.Visibility=options&&!_busy?Visibility.Visible:Visibility.Collapsed;_options.IsEnabled=allowed&&!_busy;AutomationProperties.SetName(_circle,_busy?"Coleta em andamento":state.Phase==DataLoadPhase.Failed?"Tentar coletar novamente":"Coletar dados de "+title);Animate();}
 public void Suspend(){_pulse.Stop();_ring.IsActive=false;_animating=false;}
 private void Animate(){if(!_busy||!IsLoaded){_pulse.Stop();_animating=false;return;}if(_animating)return;try{if(new Windows.UI.ViewManagement.UISettings().AnimationsEnabled){_pulse.Begin();_animating=true;}}catch(InvalidOperationException){}}
}
